using Intranet.Entity;
using Intranet.Data;
using Intranet.Service;
using Intranet.Api.Security;
using System.Security.Claims;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.FileProviders;
using Microsoft.Extensions.Options;
namespace Intranet.Api.Tests;
public sealed class ImportControlTests
{
 static ImportControlValues Valid()=>new(){Annex="0001",ItemType="371",Currency="USD",Origin="001"};
 [Fact]public void CountryAndAssociatedHaveIndependentModes(){ImportControlService.ValidateFilter(new(){Mode="D",Country="123"});ImportControlService.ValidateFilter(new(){Mode="D",Associated="20260001"});Assert.False(ImportControlService.HasPrimaryFilter(new(){Mode="D",Associated="20260001"}));ImportControlService.ValidateFilter(new(){Mode="C",Associated="20260001"});}
 [Fact]public void ReferenceDocumentRequiresTypeAndNumber(){ImportControlService.ValidateFilter(new(){Mode="3",DocumentType="FI"});Assert.False(ImportControlService.HasPrimaryFilter(new(){Mode="3",DocumentType="FI"}));ImportControlService.ValidateFilter(new(){Mode="3",DocumentType="FI",DocumentNumber="123"});}
 [Theory][InlineData(0)][InlineData(13)]public void InvalidMonthsAreRejected(int month)=>Assert.Throws<ArgumentException>(()=>ImportControlService.ValidateFilter(new(){Mode="2",Month=month}));
 [Fact]public void DateRangeCannotLeakToUnrelatedSearch(){Assert.Throws<ArgumentException>(()=>ImportControlService.ValidateFilter(new(){Mode="1",Number="20260001",From=DateTime.Today}));ImportControlService.ValidateFilter(new(){Mode="8",Status="R",From=DateTime.Today});}
 [Fact]public void ReversedRangeIsRejected()=>Assert.Throws<ArgumentException>(()=>ImportControlService.ValidateFilter(new(){Mode="8",Status="R",From=DateTime.Today,To=DateTime.Today.AddDays(-1)}));
 [Fact]public void PartialRequiresDifferentPrincipal(){var v=Valid();v.Partial=true;Assert.Throws<ArgumentException>(()=>ImportControlService.ValidateValues(v));v.Number=v.Principal="20260001";Assert.Throws<ArgumentException>(()=>ImportControlService.ValidateValues(v));v.Principal="20250001";ImportControlService.ValidateValues(v);}
 [Fact]public void LegacyParametersPreserveCountryPartialAndServerIdentity(){var v=Valid();v.Number="20260001-1";v.Partial=true;v.Principal="20260001";v.Country="123";v.Guide=" AB ";v.PaymentDate=null;var p=ImportControlRepository.Parameters("U",v,"REALUSER");Assert.Equal("REALUSER",p.Get<string>("cod_usuario"));Assert.Equal("123",p.Get<string>("ID_PAIS_DUA"));Assert.Equal("S",p.Get<string>("Flg_Liquidacion_Parcial"));Assert.Equal("20260001",p.Get<string>("Num_Importacion_Inicial"));Assert.Equal("AB",p.Get<string>("Num_Guia"));Assert.Null(p.Get<DateTime?>("Fec_Pago"));Assert.Equal("",p.Get<string>("Ser_OrdComp"));}
 [Fact]public void ControlUsesActualGestionMenuGrant(){Assert.Contains("imports",PortalAccessService.Map([new("10","mnuImpAgr")]));Assert.DoesNotContain("imports",PortalAccessService.Map([new("07","mOImportac")]));Assert.Equal(["imports"],PortalAccessFilter.Required("ImportControl","Save","POST"));}
 [Theory][InlineData(false,true)][InlineData(true,false)]public async Task ReadOnlySessionOrMissingHeaderCannotWrite(bool permission,bool header){var repo=new Repo();var identity=new GestionIdentity(Options.Create(new GestionOptions{Mode="SqlServer",EnableOrderRegistration=permission,AllowAllAuthenticatedWrites=true}),new Env());var user=new ClaimsPrincipal(new ClaimsIdentity([new Claim(ClaimTypes.Name,"gestion:OPERARIO"),new Claim(IntranetLogin.GestionUserClaim,"OPERARIO")],"Test"));var s=new ImportControlService(repo,identity,new RequestActor(user,header,false,false,true,"test"));await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>s.Save(null,new(){Values=Valid()},default));await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>s.Delete("20260001",new(){Version=new('A',64)},default));await Assert.ThrowsAsync<UnauthorizedAccessException>(()=>s.Provision("20260001",new(new('A',64),"provision"),default));Assert.Equal(0,repo.Writes);}
 [Fact]public async Task UpdateRequiresConcurrencyToken(){var repo=new Repo();var identity=new GestionIdentity(Options.Create(new GestionOptions{Mode="SqlServer",EnableOrderRegistration=true,AllowAllAuthenticatedWrites=true}),new Env());var user=new ClaimsPrincipal(new ClaimsIdentity([new Claim(ClaimTypes.Name,"gestion:OPERARIO"),new Claim(IntranetLogin.GestionUserClaim,"OPERARIO")],"Test"));var s=new ImportControlService(repo,identity,new RequestActor(user,true,false,false,true,"test"));await Assert.ThrowsAsync<ArgumentException>(()=>s.Save("20260001",new(){Values=Valid()},default));Assert.Equal(0,repo.Writes);}
 [Theory][InlineData("2026-10-23",true)][InlineData("2026-02-30",false)][InlineData("23/10/2026",false)][InlineData("",false)][InlineData("1800-01-01",false)]public async Task ExchangeRateUsesValidatedIsoDateAndNeedsNoWritePermission(string date,bool valid){var repo=new Repo();var identity=new GestionIdentity(Options.Create(new GestionOptions{Mode="SqlServer"}),new Env());var user=new ClaimsPrincipal(new ClaimsIdentity([new Claim(ClaimTypes.Name,"gestion:OPERARIO"),new Claim(IntranetLogin.GestionUserClaim,"OPERARIO")],"Test"));var service=new ImportControlService(repo,identity,new RequestActor(user,false,false,false,true,"test"));if(valid)await service.DocumentChoices("exchangeRate","","",date,default);else await Assert.ThrowsAsync<ArgumentException>(()=>service.DocumentChoices("exchangeRate","","",date,default));Assert.Equal(0,repo.Writes);}
 [Theory][InlineData("C|002|350064",true)][InlineData("R|000|123456",true)][InlineData("C|002",false)][InlineData("C|002|1234567",false)][InlineData("C|002|';drop",false)]public async Task OrderDetailOnlyAcceptsCompleteBoundedIdentity(string key,bool valid){var identity=new GestionIdentity(Options.Create(new GestionOptions{Mode="SqlServer"}),new Env());var user=new ClaimsPrincipal(new ClaimsIdentity([new Claim(ClaimTypes.Name,"gestion:OPERARIO"),new Claim(IntranetLogin.GestionUserClaim,"OPERARIO")],"Test"));var service=new ImportControlService(new Repo(),identity,new RequestActor(user,false,false,false,true,"test"));if(valid)await service.DocumentChoices("orderDetail","","",key,default);else await Assert.ThrowsAsync<ArgumentException>(()=>service.DocumentChoices("orderDetail","","",key,default));}
 [Fact]public void EmptyInitialSearchAndExplicitAllAreAllowed(){ImportControlService.ValidateFilter(new());Assert.False(ImportControlService.HasPrimaryFilter(new()));ImportControlService.ValidateFilter(new(){Mode="6"});Assert.False(ImportControlService.HasPrimaryFilter(new(){Mode="6"}));Assert.True(ImportControlService.HasPrimaryFilter(new(){Number="2026"}));}
 [Fact]public async Task ProvisionUsesAuthenticatedUserAndRequiresValidVersion(){var repo=new Repo();var identity=new GestionIdentity(Options.Create(new GestionOptions{Mode="SqlServer",EnableOrderRegistration=true,AllowAllAuthenticatedWrites=true}),new Env());var user=new ClaimsPrincipal(new ClaimsIdentity([new Claim(ClaimTypes.Name,"gestion:OPERARIO"),new Claim(IntranetLogin.GestionUserClaim,"OPERARIO")],"Test"));var service=new ImportControlService(repo,identity,new RequestActor(user,true,false,false,true,"test"));await Assert.ThrowsAsync<ArgumentException>(()=>service.Provision("20260001",new("","provision"),default));Assert.Equal(0,repo.Writes);await service.Provision("20260001",new(new('A',64),"provision"),default);Assert.Equal("OPERARIO",repo.ProvisionUser);Assert.Equal(1,repo.Writes);}
 sealed class Repo:IImportControlRepository{public int Writes;public string? ProvisionUser;public Task<ImportControlProvisionResult> Provision(string n,ImportControlProvision r,string u,CancellationToken ct){Writes++;ProvisionUser=u;return Task.FromResult(new ImportControlProvisionResult(n,r.Action,r.Action=="provision"?"P":"R"));}public Task<object> Search(ImportControlFilter f,CancellationToken ct)=>Task.FromResult<object>(new{});public Task<ImportControlCatalogs> Catalogs(CancellationToken ct)=>Task.FromResult(new ImportControlCatalogs([],true));public Task<object> Annexes(string t,string s,CancellationToken ct)=>Task.FromResult<object>(Array.Empty<object>());public Task<ImportControlDetail?> Detail(string n,CancellationToken ct)=>Task.FromResult<ImportControlDetail?>(null);public Task<object> DocumentChoices(string k,string t,string a,string s,CancellationToken ct)=>Task.FromResult<object>(new object[0]);
 public Task<object> Shipments(CancellationToken ct)=>Task.FromResult<object>(new object[0]);
 public Task<object> SaveShipment(ImportControlShipmentSave r,string u,CancellationToken ct)=>Task.FromResult<object>(new{saved=true});
 public Task<object> Invoices(string n,CancellationToken ct)=>Task.FromResult<object>(Array.Empty<object>());public Task<string> Save(string? n,ImportControlSave r,string u,CancellationToken ct){Writes++;return Task.FromResult(n??"20260001");}public Task Delete(string n,string v,string u,CancellationToken ct){Writes++;return Task.CompletedTask;}}
 sealed class Env:IHostEnvironment{public string ApplicationName{get;set;}="Test";public string EnvironmentName{get;set;}="Production";public string ContentRootPath{get;set;}="";public IFileProvider ContentRootFileProvider{get;set;}=new NullFileProvider();}
}
